<template>    <div class="calendar">        <CalendarControl            class="calendar-control"            :month="month"            :year="year"            @click:prev="prevMonth"            @click:next="nextMonth"            @click:reset="resetDate"        />        <div class="content">            <CalendarDays                class="calendar-days"            />            <div class="cell-list">                <div                    v-for="day of calendarGenerated"                    :key="day?.dayInfo.dayIndex"                    class="cell"                >                    <CalendarCell                        :dayData="day"                        @click="setPopupData(day)"                    />                </div>            </div>        </div>        <transition name="fade">            <DayPopup                v-if="popupData"                :dayData="popupData"                @close="setPopupData(null)"            />        </transition>    </div></template><script lang="ts" setup>// Импортыimport {useAsyncData, useRoute, useRouter} from "#app";import {ref, watch} from "#imports";import {    type ISerialEpisodeWithSerialInfo,    type TCalendar,    type TDay,    MonthsEnum,} from "~/appModules/calendar/calendarTypes";import CalendarHelper from "~/appModules/calendar/CalendarHelper";import dateHelper from "~/appModules/common/helpers/DateHelper";import calendarService from "~/appModules/calendar/CalendarService";import CalendarCell from "~/appModules/calendar/components/CalendarCell.vue";import CalendarDays from "~/appModules/calendar/components/CalendarDays.vue";import CalendarControl from "~/appModules/calendar/components/CalendarControl.vue";import DayPopup from "~/appModules/calendar/components/DayPopup.vue";// Composableconst route = useRoute();const router = useRouter();// Valuesconst month = ref<MonthsEnum>(MonthsEnum.January);const year = ref<number>(2000);const calendarGenerated = ref<[] | TCalendar>([]);const popupData = ref<null | TDay>(null);// Initmonth.value = route.query.month as MonthsEnum;year.value = Number(route.query.year);const {data: calendarData} = await useAsyncData(() => fetchMonthData());generateCalendar();// Watcherswatch(month, async (newMonth, oldMonth) => {    calendarData.value = [];    calendarData.value = await fetchMonthData();    generateCalendar();    updateQuery();})// Methodsasync function fetchMonthData() {    return calendarService.getEpisodesByMonthAndYear(month.value, year.value);}function generateCalendar() {    const calendar = new CalendarHelper({        month: month.value as MonthsEnum,        year: year.value,        content: calendarData.value as ISerialEpisodeWithSerialInfo[],    });    calendarGenerated.value = calendar.getCalendar();}function prevMonth() {    const newDate = new Date(        year.value,        dateHelper.getMonthIndex(month.value as MonthsEnum) - 1,    );    month.value = dateHelper.getMonthNameByIndex(newDate.getMonth());    year.value = newDate.getFullYear();}function nextMonth() {    const newDate = new Date(        year.value,        dateHelper.getMonthIndex(month.value as MonthsEnum) + 1,    );    month.value = dateHelper.getMonthNameByIndex(newDate.getMonth());    year.value = newDate.getFullYear();}function resetDate() {    const newDate = new Date();    month.value = dateHelper.getMonthNameByIndex(newDate.getMonth());    year.value = newDate.getFullYear();}function updateQuery() {    router.push({        query: {            month: month.value,            year: year.value,        },    });}function setPopupData(day: TDay) {    popupData.value = day;}</script><style scoped>.calendar {    display: flex;    flex-direction: column;    height: 100vh;    padding: 20px;}.calendar-control {    margin-bottom: 80px;}.calendar-days {    margin-bottom: 20px;}.content {    display: flex;    flex-direction: column;    height: 100%;}.cell-list {    flex: 1;    display: grid;    grid-template-columns: repeat(7, 1fr);    gap: 8px;}.fade-enter-active,.fade-leave-active {    transition: opacity 0.5s ease;}.fade-enter-from,.fade-leave-to {    opacity: 0;}</style>